using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got JsonTypeInfo<Person>  – Type: {personInfo.Type.Name}");

// 2) Probe without throwing: TryGetTypeInfo returns false if metadata isn't available.
bool found = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"TryGetTypeInfo(Person)   – found: {found}, info null: {info is null}");

// Probe for a type whose metadata might NOT be resolvable (e.g. with a
// custom resolver that only handles Person).
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(new PersonOnlyResolver())
};

bool foundOrder = limited.TryGetTypeInfo(typeof(Order), out JsonTypeInfo? orderInfo);
Console.WriteLine($"TryGetTypeInfo(Order)    – found: {foundOrder}, info null: {orderInfo is null}");

// Confirm the limited resolver DOES resolve Person.
bool foundPerson = limited.TryGetTypeInfo(typeof(Person), out _);
Console.WriteLine($"TryGetTypeInfo(Person)   – found: {foundPerson} (limited resolver)");

// --- Types ---
public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

// A resolver that only provides metadata for Person.
file class PersonOnlyResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
        => type == typeof(Person) ? _inner.GetTypeInfo(type, options) : null;
}

